async function storage(path,options={}){const user=uid,s=await portalAuth.getSession();if(s.error||!s.data.session)throw Error('نشست ورود پایان یافته است.');const r=await fetch(SUPABASE_ENDPOINT+'/storage/v1/'+path,{...options,headers:{apikey:KEY,Authorization:'Bearer '+s.data.session.access_token,...options.headers}}),result=await r.json().catch(()=>({}));if(uid!==user)throw Error('حساب تغییر کرده است.');if(!r.ok){const e=Error(result.message||result.error||'ارتباط با فایل برقرار نشد.');e.status=r.status;throw e;}return result;}
